CREATE TABLE partite (
  id_partita int NOT NULL AUTO_INCREMENT,
  `data` date DEFAULT NULL,
  id_squadra_casa int DEFAULT NULL,
  id_squadra_trasferta int DEFAULT NULL,
  nome_squadra_casa varchar(50) DEFAULT NULL,
  nome_squadra_trasferta varchar(50) DEFAULT NULL,
  gol_casa int DEFAULT NULL,
  gol_trasferta int DEFAULT NULL,
  stadio_id int DEFAULT NULL,
  nome_stadio varchar(50) DEFAULT NULL,
  giornata int DEFAULT NULL,
  stagione varchar(9) DEFAULT NULL,
  PRIMARY KEY (id_partita),
  KEY id_squadra_casa (id_squadra_casa),
  KEY id_squadra_trasferta (id_squadra_trasferta),
  KEY stadio_id (stadio_id),
  CONSTRAINT partite_ibfk_1 FOREIGN KEY (id_squadra_casa) REFERENCES squadra (id_squadra),
  CONSTRAINT partite_ibfk_2 FOREIGN KEY (id_squadra_trasferta) REFERENCES squadra (id_squadra),
  CONSTRAINT partite_ibfk_3 FOREIGN KEY (stadio_id) REFERENCES stadio (id_stadio)
)

